// $service-tab-nav-height: 60px;\n$service-tab-nav-height: 70px;\n$media-footer-height: 74px;\n$media-bar-height: 82px;\n$mobile-media-bar-height: 60px;\n$fav-actions-height: 112px;\n$mobile-fav-actions-height: 60px;\n$mobile-nav-height: 93px;\n$mobile-volume-bar-height: 50px;\n\n$breakpointWidthPhone: 595px;\n$breakpointHeightPhone: 897px;\n$sidebarHeight: 12.5%;\n\n// Color Variables\n$armedColor: #e9344a;\n$troubleColor: #fc474b;\n$disarmedColor: #4cffa9;\n$isArmingColour: #FFB700;\n$altIsArmingColour: #ff6800;\n$notReadyColour: #d4fb0c;\n$grey800: #191820;\n$grey750: #242429;\n$grey700: #35343c;\n$grey600: #303037;\n$grey500: #383840;\n$grey450: #47474e;\n$grey400: #7e7e7e;\n$purple: #7a3ff8;\n$coolBlue: #43b3f5;\n$red: #fc474b;\n$cable-red: #e12c59;\n$cable-green: #79ca6d;\n$cable-yellow: #ffcd1d;\n$cable-blue: #4d69fd;\n\n//Fonts\n$mainFont: 'SupermolotNeue';\n$mainFontLight: 'SupermolotNeueLight';\n$mainFontMedium: 'SupermolotNeueMedium';\n$mainFontBold: 'SupermolotNeueBold';\n$mainFontDemiBold: 'SupermolotNeueDemiBold';\n\n$mainBackgroundLinearGradient: linear-gradient(180deg, #2c2c37 0%, #09090e 87.45%);\n\n@function convertToVH($pixelSize, $screenHeight: $screenHeightDef) {\n    $vh: calc($pixelSize / ($screenHeight / 100));\n    @if ($vh % 1 != 0) {\n        $vh: decimal-round($vh, 3);\n    }\n    @return $vh * 1vh;\n    // @return calc(100 * ($pixelSize / $screenHeight)) * 1.5vh;\n}\n\n@function convertToVW($pixelSize, $screenWidth: $screenWidthDef) {\n    $vw: calc($pixelSize / ($screenWidth / 100));\n    @if ($vw % 1 != 0) {\n        $vw: decimal-round($vw, 3);\n    }\n    // @return calc(100 * ($pixelSize / $screenWidth)) * 1.5vw;\n    @return $vw * 1vw;\n}\n\n/* Viewport width unit (vw) = 100 * (Pixel Unit Size / Viewport width) */\n@function decimal-round($number, $digits: 0, $mode: round) {\n    $n: 1;\n    // $number must be a number\n    @if type-of($number) != number {\n        @warn '#{ $number } is not a number.';\n        @return $number;\n    }\n    // $digits must be a unitless number\n    @if type-of($digits) != number {\n        @warn '#{ $digits } is not a number.';\n        @return $number;\n    } @else if not unitless($digits) {\n        @warn '#{ $digits } has a unit.';\n        @return $number;\n    }\n    @if $digits > 0 {\n        @for $i from 1 through $digits {\n            $n: $n * 10;\n        }\n    }\n    @if $mode == round {\n        @return calc(round($number * $n) / $n);\n    } @else if $mode == ceil {\n        @return ceil($number * $n) / $n;\n    } @else if $mode == floor {\n        @return floor($number * $n) / $n;\n    } @else {\n        @warn '#{ $mode } is undefined keyword.';\n        @return $number;\n    }\n}\n\n// Mixins\n@mixin centerAlignAbsolute {\n    left: 0;\n    right: 0;\n    margin-left: auto;\n    margin-right: auto;\n    text-align: center;\n}\n\n@mixin leftAlignAbsolute {\n    left: 30px;\n}\n\n@mixin rightAlignAbsolute {\n    right: 30px;\n}\n\n@mixin hideScrollbar {\n    &::-webkit-scrollbar {\n        display: none;\n    }\n}\n\n@keyframes slowAppear {\n    0% {\n        opacity: 0;\n    }\n    100% {\n        opacity: 1;\n    }\n}\n\n@keyframes slowDisappear {\n    0% {\n        opacity: 1;\n    }\n    100% {\n        opacity: 0;\n    }\n}\n\n$mainScrollingSectionHeight: 67.6vh;\n\n@mixin mainScrollingSectionHeight() {\n    height: $mainScrollingSectionHeight;\n}\n",'@import "static.scss";\n// .full-modals\n.camera-modal__control {\n    position: absolute;\n    z-index: 100;\n    top: 0px;\n    left: 0px;\n    bottom: 0px;\n    right: 0px;\n    text-transform: uppercase;\n    pointer-events: auto;\n    isolation: isolate;\n    height: 100vh;\n    width: 100vw;\n\n    .webrtc-video-stream {\n        width: inherit;\n        height: inherit;\n\n        video {\n            width: inherit;\n            height: inherit;\n            object-fit: fill;\n        }\n    }\n\n    .camera-modal__control__direction {\n        .the-one-button {\n            height: 40px;\n        }\n    }\n\n    .camera-modal__control__zoom {\n        .the-one-button {\n            height: 60px;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            align-items: center;\n            gap: 10px;\n\n            &.camera-modal__control__overlay_zoom-out {\n                flex-direction: column-reverse;\n            }\n        }\n    }\n\n    .camera-modal-image-container-background {\n        width: 100vw;\n        height: 100vh;\n\n        img {\n            height: inherit;\n            width: inherit;\n        }\n    }\n\n    .camera-modal__control__direction {\n        position: fixed;\n        top: 50%;\n        left: 50%;\n        transform: translate(-50%, -50%);\n        display: grid;\n        grid-template-columns: 1fr 1fr 1fr;\n        grid-template-rows: 1fr 1fr 1fr;\n        gap: 40px; // spacing between buttons\n        width: 300px;\n        height: 300px;\n        place-items: center;\n    }\n\n    .camera-modal__control__direction-up {\n        grid-column: 2;\n        grid-row: 1;\n\n        svg {\n            transform: rotate(90deg);\n        }\n    }\n\n    .camera-modal__control__direction-left {\n        grid-column: 1;\n        grid-row: 2;\n\n        svg {\n            transform: rotate(0deg);\n        }\n    }\n\n    .camera-modal__control__direction-right {\n        grid-column: 3;\n        grid-row: 2;\n\n        svg {\n            transform: rotate(180deg);\n        }\n    }\n\n    .camera-modal__control__direction-down {\n        grid-column: 2;\n        grid-row: 3;\n\n        svg {\n            transform: rotate(270deg);\n        }\n    }\n\n    .camera-modal__control__zoom {\n        position: absolute;\n        display: flex;\n        flex-direction: column;\n        justify-content: space-around;\n        top: 107px;\n        left: 91%;\n        right: auto;\n        width: 86px;\n        height: 588px;\n        text-shadow: 0px 0px 19px #15151C;\n        font-weight: 500;\n        font-size: 12px;\n        line-height: 14px;\n        text-align: center;\n        text-transform: uppercase;\n    }\n\n    .camera-modal__control__overlay {\n        position: absolute;\n        top: 107px;\n        left: 30px;\n        font-weight: 500;\n        font-size: 12px;\n        line-height: 14px;\n        text-align: center;\n        text-transform: uppercase;\n        width: 86px;\n        height: 588px;\n        color: #FFFFFF;\n        text-shadow: 0px 0px 19px #15151C;\n    }\n\n    .camera-modal__control__overlay_middle,\n    .camera-modal__control__zoom {\n        // background: linear-gradient(180deg, rgba(14, 14, 20, 0) 0%, #0E0E14 52.66%, rgba(14, 14, 20, 0) 100%);\n        backdrop-filter: blur(15px);\n        width: 86px;\n        height: 516px;\n        margin-top: 8px;\n        margin-bottom: 8px;\n        padding-top: 24px;\n        padding-bottom: 24px;\n    }\n\n    .camera-modal__control__hide {\n        text-transform: uppercase;\n        width: fit-content;\n        height: 28px;\n        background: rgb(64, 63, 72);\n        border-radius: 4px;\n        color: white;\n        font-weight: 500;\n        font-size: 12px;\n        line-height: 100%;\n        margin-left: auto;\n        margin-right: auto;\n        left: 0;\n        right: 0;\n        position: fixed;\n        top: 33px;\n    }\n\n    .ptz-zoom-in-icon {\n        height: 3vh;\n        width: 2.6vw;\n    }\n\n    .ptz-zoom-out-icon {\n        height: 3vh;\n        width: 2.6vw;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n    }\n\n    .camera-modal__control__zoom-in {\n        position: relative;\n        top: 8vh;\n    }\n\n    .camera-modal__control__overlay_zoom-out {\n        position: relative;\n        top: -8vh;\n    }\n\n    .ptz-overlay-background {\n        position: absolute;\n        width: 100vw;\n        height: 100vh;\n        top: 0px;\n        left: 0px;\n\n        &.hide.controls {\n            display: none;\n        }\n    }\n\n    .camera-modal__control__direction-up,\n    .camera-modal__control__direction-left,\n    .camera-modal__control__direction-right,\n    .camera-modal__control__direction-down,\n    .camera-modal__control__zoom-in,\n    .camera-modal__control__overlay_zoom-out {\n        cursor: pointer;\n    }\n\n    .camera-modal__control__presets {\n        position: absolute;\n        bottom: 0vh;\n        height: 18vh;\n        width: 100vw;\n\n        .camera-preset-container {\n            display: flex;\n            justify-content: center;\n            align-items: flex-end;\n        }\n\n        .camera-ptz-preset-toggle {\n            position: absolute;\n            bottom: 6vh;\n            width: 100px;\n            font-size: 12px;\n            text-transform: uppercase;\n\n            svg {\n                position: relative;\n                top: 2vh;\n                scale: 0.3;\n            }\n        }\n\n        &.show-presets {\n            .camera-ptz-preset-toggle {\n                bottom: 19vh;\n\n                svg {\n                    rotate: 180deg;\n                }\n            }\n        }\n\n        .camera-ptz-preset-list {\n            height: 107px;\n            background-color: #0B0B10;\n            opacity: 0.69;\n            display: flex;\n            flex-direction: row;\n            gap: 30px;\n            justify-content: flex-start;\n            width: 100vw;\n            left: 0;\n            position: absolute;\n            bottom: 0vh;\n            align-items: center;\n            overflow-x: scroll;\n\n            &:first-child {\n                margin-left: 30px;\n            }\n\n            button {\n                &:first-child {\n                    margin-left: 30px;\n                }\n\n                &.active {\n                    &::before {\n                        content: "";\n                        width: 80px;\n                        height: 40px;\n            